=== FILE: apb_gpio.v ===
`timescale 1ns/1ps
// apb_gpio: general-purpose I/O, up to 32 pins, behind an APB4 completer.
// Implements microarchitecture.md (approved) for interface_spec.md (approved).
// Zero wait states, synchronous active-low reset, single clock (pclk).
module apb_gpio #(
  parameter integer ADDR_WIDTH = 8,   // byte address width; decode needs >= 7, spec requires 8
  parameter integer N          = 8    // number of pins, 1 to 32
) (
  input  wire                  pclk,
  input  wire                  presetn,
  input  wire [ADDR_WIDTH-1:0] paddr,
  input  wire                  psel,
  input  wire                  penable,
  input  wire                  pwrite,
  input  wire [31:0]           pwdata,
  input  wire [3:0]            pstrb,
  output wire [31:0]           prdata,
  output wire                  pready,
  output wire                  pslverr,
  input  wire [N-1:0]          gpio_in,
  output wire [N-1:0]          gpio_out,
  output wire [N-1:0]          gpio_oe,
  output wire                  irq
);

  // Register indices, paddr[5:2] (interface_spec section 3).
  localparam [3:0] IDX_DATA_OUT = 4'd0;
  localparam [3:0] IDX_DIR      = 4'd1;
  localparam [3:0] IDX_DATA_IN  = 4'd2;
  localparam [3:0] IDX_RISE     = 4'd3;
  localparam [3:0] IDX_FALL     = 4'd4;
  localparam [3:0] IDX_HIGH     = 4'd5;
  localparam [3:0] IDX_LOW      = 4'd6;
  localparam [3:0] IDX_ENABLE   = 4'd7;
  localparam [3:0] IDX_STATUS   = 4'd8;

  // Constant pin mask: bits 0 to N-1 set (microarchitecture section 2).
  localparam [32:0] PINS_W = (33'h1 << N) - 33'h1;
  localparam [31:0] PINS   = PINS_W[31:0];

  // ---------------------------------------------------------------- decode
  wire        access   = psel & penable;               // completing cycle (pready is 1)
  wire [3:0]  idx      = paddr[5:2];
  wire        upper_ok = (paddr[ADDR_WIDTH-1:6] == {(ADDR_WIDTH-6){1'b0}});
  wire        mapped   = (paddr[1:0] == 2'b00) & upper_ok & (idx <= IDX_STATUS);
  wire        wr_acc   = access & pwrite & mapped;
  wire        rd_acc   = access & ~pwrite & mapped;

  wire [31:0] wmask    = {{8{pstrb[3]}}, {8{pstrb[2]}}, {8{pstrb[1]}}, {8{pstrb[0]}}} & PINS;
  wire [31:0] wbits    = pwdata & wmask;

  wire        we_out   = wr_acc & (idx == IDX_DATA_OUT);
  wire        we_dir   = wr_acc & (idx == IDX_DIR);
  wire        we_rise  = wr_acc & (idx == IDX_RISE);
  wire        we_fall  = wr_acc & (idx == IDX_FALL);
  wire        we_high  = wr_acc & (idx == IDX_HIGH);
  wire        we_low   = wr_acc & (idx == IDX_LOW);
  wire        we_en    = wr_acc & (idx == IDX_ENABLE);
  wire        we_stat  = wr_acc & (idx == IDX_STATUS);

  // ------------------------------------------------------------- registers
  reg  [31:0] data_out_q;
  reg  [31:0] dir_q;
  reg  [31:0] rise_q;
  reg  [31:0] fall_q;
  reg  [31:0] high_q;
  reg  [31:0] low_q;
  reg  [31:0] en_q;
  reg  [31:0] status_q;
  reg  [31:0] in_q;        // last sample, read as DATA_IN
  reg  [31:0] in_prev_q;   // the sample before it

  // gpio_in widened to 32 bits, zeros above N.
  wire [31:0] in_w;
  generate
    if (N < 32) begin : g_pad
      assign in_w = {{(32-N){1'b0}}, gpio_in};
    end else begin : g_full
      assign in_w = gpio_in;
    end
  endgenerate

  // Byte-merged writes: (old & ~mask) | (pwdata & mask).
  wire [31:0] data_out_d = we_out  ? ((data_out_q & ~wmask) | wbits) : data_out_q;
  wire [31:0] dir_d      = we_dir  ? ((dir_q      & ~wmask) | wbits) : dir_q;
  wire [31:0] rise_d     = we_rise ? ((rise_q     & ~wmask) | wbits) : rise_q;
  wire [31:0] fall_d     = we_fall ? ((fall_q     & ~wmask) | wbits) : fall_q;
  wire [31:0] high_d     = we_high ? ((high_q     & ~wmask) | wbits) : high_q;
  wire [31:0] low_d      = we_low  ? ((low_q      & ~wmask) | wbits) : low_q;
  wire [31:0] en_d       = we_en   ? ((en_q       & ~wmask) | wbits) : en_q;

  // Detection and status (microarchitecture section 3). Detection last: it beats a clear.
  wire [31:0] rise_ev  = in_q & ~in_prev_q;
  wire [31:0] fall_ev  = ~in_q & in_prev_q;
  wire [31:0] detected = ((rise_ev & rise_q) | (fall_ev & fall_q)
                         | (in_q & high_q) | (~in_q & low_q)) & PINS;
  wire [31:0] clr_bits = we_stat ? wbits : 32'h0000_0000;
  wire [31:0] status_d = (status_q & ~clr_bits) | detected;

  always @(posedge pclk) begin
    if (!presetn) begin
      data_out_q <= 32'h0000_0000;
      dir_q      <= 32'h0000_0000;
      rise_q     <= 32'h0000_0000;
      fall_q     <= 32'h0000_0000;
      high_q     <= 32'h0000_0000;
      low_q      <= 32'h0000_0000;
      en_q       <= 32'h0000_0000;
      status_q   <= 32'h0000_0000;
      in_q       <= 32'h0000_0000;
      in_prev_q  <= 32'h0000_0000;
    end else begin
      data_out_q <= data_out_d;
      dir_q      <= dir_d;
      rise_q     <= rise_d;
      fall_q     <= fall_d;
      high_q     <= high_d;
      low_q      <= low_d;
      en_q       <= en_d;
      status_q   <= status_d;
      in_q       <= in_w;
      in_prev_q  <= in_q;
    end
  end

  // ------------------------------------------------------------- read path
  reg [31:0] rdata_mux;
  always @* begin
    case (idx)
      IDX_DATA_OUT: rdata_mux = data_out_q;
      IDX_DIR:      rdata_mux = dir_q;
      IDX_DATA_IN:  rdata_mux = in_q;
      IDX_RISE:     rdata_mux = rise_q;
      IDX_FALL:     rdata_mux = fall_q;
      IDX_HIGH:     rdata_mux = high_q;
      IDX_LOW:      rdata_mux = low_q;
      IDX_ENABLE:   rdata_mux = en_q;
      IDX_STATUS:   rdata_mux = status_q;
      default:      rdata_mux = 32'h0000_0000;
    endcase
  end

  assign prdata   = rd_acc ? rdata_mux : 32'h0000_0000;
  assign pready   = 1'b1;
  assign pslverr  = access & (~mapped | (pwrite & (idx == IDX_DATA_IN)));

  assign gpio_out = data_out_q[N-1:0];
  assign gpio_oe  = dir_q[N-1:0];
  assign irq      = |(status_q & en_q);

`ifdef FORMAL
  // Design-intent assertions (not proven by this submission).
  always @(*) begin
    assert (pready == 1'b1);
    if (!access) assert (pslverr == 1'b0);
    if (!rd_acc) assert (prdata == 32'h0000_0000);
    assert ((status_q & ~PINS) == 32'h0000_0000);
  end
`endif

endmodule
=== END FILE ===
=== FILE: apb_gpio_tb.v ===
`timescale 1ns/1ps
// Self-checking testbench for apb_gpio (interface_spec.md section 8).
// Two instances, N=8 and N=32, share one APB bus with separate psel.
// Stimulus changes after the falling edge; the DUT samples on the rising edge.
module apb_gpio_tb;

  localparam [7:0] A_OUT  = 8'h00;
  localparam [7:0] A_DIR  = 8'h04;
  localparam [7:0] A_IN   = 8'h08;
  localparam [7:0] A_RISE = 8'h0C;
  localparam [7:0] A_FALL = 8'h10;
  localparam [7:0] A_HIGH = 8'h14;
  localparam [7:0] A_LOW  = 8'h18;
  localparam [7:0] A_EN   = 8'h1C;
  localparam [7:0] A_STAT = 8'h20;
  localparam       S8     = 1'b0;
  localparam       S32    = 1'b1;

  reg         pclk;
  reg         presetn;
  reg  [7:0]  paddr;
  reg         psel8;
  reg         psel32;
  reg         penable;
  reg         pwrite;
  reg  [31:0] pwdata;
  reg  [3:0]  pstrb;
  reg  [7:0]  gpio_in8;
  reg  [31:0] gpio_in32;

  wire [31:0] prdata8;
  wire [31:0] prdata32;
  wire        pready8;
  wire        pready32;
  wire        pslverr8;
  wire        pslverr32;
  wire [7:0]  gpio_out8;
  wire [7:0]  gpio_oe8;
  wire [31:0] gpio_out32;
  wire [31:0] gpio_oe32;
  wire        irq8;
  wire        irq32;

  reg         cur_sel;
  wire [31:0] cur_prdata  = cur_sel ? prdata32  : prdata8;
  wire        cur_pready  = cur_sel ? pready32  : pready8;
  wire        cur_pslverr = cur_sel ? pslverr32 : pslverr8;

  integer          passed;
  integer          failed;
  integer          test_id;
  integer          got_nonce;
  reg [8*64-1:0]   nonce;

  apb_gpio #(.ADDR_WIDTH(8), .N(8)) u8 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel8), .penable(penable),
    .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata8), .pready(pready8),
    .pslverr(pslverr8), .gpio_in(gpio_in8), .gpio_out(gpio_out8), .gpio_oe(gpio_oe8),
    .irq(irq8)
  );

  apb_gpio #(.ADDR_WIDTH(8), .N(32)) u32 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel32), .penable(penable),
    .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata32), .pready(pready32),
    .pslverr(pslverr32), .gpio_in(gpio_in32), .gpio_out(gpio_out32), .gpio_oe(gpio_oe32),
    .irq(irq32)
  );

  initial pclk = 1'b0;
  always #5 pclk = ~pclk;

  // ------------------------------------------------------------ checking
  task check32;
    input [31:0] got;
    input [31:0] exp;
    begin
      if (got === exp) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("FAIL test %0d at %0t: got %h, expected %h", test_id, $time, got, exp);
      end
    end
  endtask

  task check1;
    input got;
    input exp;
    begin
      if (got === exp) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("FAIL test %0d at %0t: got %b, expected %b", test_id, $time, got, exp);
      end
    end
  endtask

  task tick;
    input integer n;
    begin
      repeat (n) @(negedge pclk);
    end
  endtask

  // Expected merge of a strobed write (independent model of interface_spec section 3).
  function [31:0] merge;
    input [31:0] old_v;
    input [31:0] d;
    input [3:0]  s;
    input [31:0] pins;
    reg   [31:0] m;
    begin
      m = {{8{s[3]}}, {8{s[2]}}, {8{s[1]}}, {8{s[0]}}} & pins;
      merge = (old_v & ~m) | (d & m);
    end
  endfunction

  // One APB transfer. Call just after a falling edge; returns just after a falling edge.
  task xfer;
    input        sel;
    input        wr;
    input [7:0]  a;
    input [31:0] d;
    input [3:0]  s;
    input [31:0] exp_rdata;
    input        exp_err;
    begin
      cur_sel = sel;
      paddr   = a;
      pwrite  = wr;
      pwdata  = wr ? d : 32'h0000_0000;
      pstrb   = wr ? s : 4'h0;
      psel8   = ~sel;
      psel32  = sel;
      penable = 1'b0;
      #1;
      check32(cur_prdata, 32'h0000_0000);   // setup phase: prdata zero
      check1(cur_pslverr, 1'b0);            // setup phase: pslverr zero
      @(negedge pclk);
      penable = 1'b1;
      #1;
      check1(cur_pready, 1'b1);
      check1(cur_pslverr, exp_err);
      if (!wr) check32(cur_prdata, exp_rdata);
      @(negedge pclk);
      psel8   = 1'b0;
      psel32  = 1'b0;
      penable = 1'b0;
      pwrite  = 1'b0;
      pstrb   = 4'h0;
    end
  endtask

  task wr_ok;
    input sel; input [7:0] a; input [31:0] d; input [3:0] s;
    begin xfer(sel, 1'b1, a, d, s, 32'h0000_0000, 1'b0); end
  endtask

  task wr_err;
    input sel; input [7:0] a; input [31:0] d; input [3:0] s;
    begin xfer(sel, 1'b1, a, d, s, 32'h0000_0000, 1'b1); end
  endtask

  task rd_ok;
    input sel; input [7:0] a; input [31:0] e;
    begin xfer(sel, 1'b0, a, 32'h0000_0000, 4'h0, e, 1'b0); end
  endtask

  task rd_err;
    input sel; input [7:0] a;
    begin xfer(sel, 1'b0, a, 32'h0000_0000, 4'h0, 32'h0000_0000, 1'b1); end
  endtask

  task chk_pins;
    input sel; input [7:0] a; input [31:0] v;
    begin
      if (a == A_OUT) check32(sel ? gpio_out32 : {24'h000000, gpio_out8}, v);
      if (a == A_DIR) check32(sel ? gpio_oe32  : {24'h000000, gpio_oe8},  v);
    end
  endtask

  // Strobe lanes and bits above N on one read/write register.
  task lane_test;
    input       sel;
    input [7:0] a;
    reg  [31:0] pins;
    reg  [31:0] v;
    begin
      pins = sel ? 32'hFFFF_FFFF : 32'h0000_00FF;
      v    = 32'h0000_0000;
      wr_ok(sel, a, 32'h0000_0000, 4'hF); v = merge(v, 32'h0000_0000, 4'hF, pins);
      rd_ok(sel, a, v); chk_pins(sel, a, v);
      wr_ok(sel, a, 32'hFFFF_FFFF, 4'hF); v = merge(v, 32'hFFFF_FFFF, 4'hF, pins);
      rd_ok(sel, a, v); chk_pins(sel, a, v);
      wr_ok(sel, a, 32'h0000_0000, 4'b0010); v = merge(v, 32'h0000_0000, 4'b0010, pins);
      rd_ok(sel, a, v); chk_pins(sel, a, v);
      wr_ok(sel, a, 32'h1234_5678, 4'b1001); v = merge(v, 32'h1234_5678, 4'b1001, pins);
      rd_ok(sel, a, v); chk_pins(sel, a, v);
      wr_ok(sel, a, 32'hDEAD_BEEF, 4'b0000); v = merge(v, 32'hDEAD_BEEF, 4'b0000, pins);
      rd_ok(sel, a, v); chk_pins(sel, a, v);
      wr_ok(sel, a, 32'hA5C3_5A3C, 4'b0100); v = merge(v, 32'hA5C3_5A3C, 4'b0100, pins);
      rd_ok(sel, a, v); chk_pins(sel, a, v);
      wr_ok(sel, a, 32'h0000_0000, 4'hF); v = 32'h0000_0000;
      rd_ok(sel, a, v); chk_pins(sel, a, v);
    end
  endtask

  task read_regs;
    input sel;
    input [31:0] e_out; input [31:0] e_dir; input [31:0] e_in;
    input [31:0] e_rise; input [31:0] e_fall; input [31:0] e_high;
    input [31:0] e_low; input [31:0] e_en; input [31:0] e_stat;
    begin
      rd_ok(sel, A_OUT,  e_out);
      rd_ok(sel, A_DIR,  e_dir);
      rd_ok(sel, A_IN,   e_in);
      rd_ok(sel, A_RISE, e_rise);
      rd_ok(sel, A_FALL, e_fall);
      rd_ok(sel, A_HIGH, e_high);
      rd_ok(sel, A_LOW,  e_low);
      rd_ok(sel, A_EN,   e_en);
      rd_ok(sel, A_STAT, e_stat);
    end
  endtask

  task bad_addr;
    input [7:0] a;
    begin
      wr_err(S8,  a, 32'hFFFF_FFFF, 4'hF);
      rd_err(S8,  a);
      wr_err(S32, a, 32'hFFFF_FFFF, 4'hF);
      rd_err(S32, a);
    end
  endtask

  task chk_reset_outputs;
    begin
      check32({24'h000000, gpio_out8}, 32'h0000_0000);
      check32({24'h000000, gpio_oe8},  32'h0000_0000);
      check1(irq8, 1'b0);
      check32(gpio_out32, 32'h0000_0000);
      check32(gpio_oe32,  32'h0000_0000);
      check1(irq32, 1'b0);
      check32(prdata8, 32'h0000_0000);
      check32(prdata32, 32'h0000_0000);
      check1(pslverr8, 1'b0);
      check1(pslverr32, 1'b0);
    end
  endtask

  // ---------------------------------------------------------------- main
  initial begin
    passed    = 0;
    failed    = 0;
    test_id   = 0;
    nonce     = 512'h0;
    got_nonce = $value$plusargs("nirmaan_nonce=%s", nonce);
    if (got_nonce == 0) $display("note: no nirmaan_nonce plusarg given");

    presetn   = 1'b0;
    psel8     = 1'b0;
    psel32    = 1'b0;
    penable   = 1'b0;
    pwrite    = 1'b0;
    paddr     = 8'h00;
    pwdata    = 32'h0000_0000;
    pstrb     = 4'h0;
    gpio_in8  = 8'h00;
    gpio_in32 = 32'h0000_0000;
    cur_sel   = 1'b0;

    // T1: reset
    test_id = 1;
    tick(3);
    chk_reset_outputs;
    presetn = 1'b1;
    tick(1);

    // T2: reset values of every register
    test_id = 2;
    read_regs(S8,  32'h0, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0);
    read_regs(S32, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0);

    // T3: strobe lanes and bits above N, every read/write register
    test_id = 3;
    lane_test(S8, A_OUT);  lane_test(S32, A_OUT);
    lane_test(S8, A_DIR);  lane_test(S32, A_DIR);
    lane_test(S8, A_RISE); lane_test(S32, A_RISE);
    lane_test(S8, A_FALL); lane_test(S32, A_FALL);
    lane_test(S8, A_HIGH); lane_test(S32, A_HIGH);
    lane_test(S8, A_LOW);  lane_test(S32, A_LOW);
    lane_test(S8, A_EN);   lane_test(S32, A_EN);

    // T4: clear status left by the low-level enables during T3
    test_id = 4;
    wr_ok(S8,  A_STAT, 32'hFFFF_FFFF, 4'hF);
    wr_ok(S32, A_STAT, 32'hFFFF_FFFF, 4'hF);
    rd_ok(S8,  A_STAT, 32'h0000_0000);
    rd_ok(S32, A_STAT, 32'h0000_0000);
    check1(irq8, 1'b0);
    check1(irq32, 1'b0);

    // T5: DATA_IN sampling, read only
    test_id = 5;
    gpio_in8  = 8'h5A;
    gpio_in32 = 32'hC3A5_5A3C;
    tick(1);
    rd_ok(S8,  A_IN, 32'h0000_005A);
    rd_ok(S32, A_IN, 32'hC3A5_5A3C);
    wr_err(S8,  A_IN, 32'hFFFF_FFFF, 4'hF);
    wr_err(S32, A_IN, 32'h0000_0000, 4'hF);
    rd_ok(S8,  A_IN, 32'h0000_005A);
    rd_ok(S32, A_IN, 32'hC3A5_5A3C);
    wr_ok(S8, A_DIR, 32'h0000_00FF, 4'hF);
    wr_ok(S8, A_OUT, 32'h0000_000F, 4'hF);
    check32({24'h000000, gpio_oe8},  32'h0000_00FF);
    check32({24'h000000, gpio_out8}, 32'h0000_000F);
    rd_ok(S8, A_IN, 32'h0000_005A);
    wr_ok(S8, A_DIR, 32'h0000_0000, 4'hF);
    wr_ok(S8, A_OUT, 32'h0000_0000, 4'hF);
    gpio_in8 = 8'hA5;                       // changed before edge E, read after E
    rd_ok(S8, A_IN, 32'h0000_00A5);
    gpio_in8  = 8'h00;
    gpio_in32 = 32'h0000_0000;
    tick(2);
    rd_ok(S8,  A_IN, 32'h0000_0000);
    rd_ok(S32, A_IN, 32'h0000_0000);

    // T6: PSLVERR policy, unmapped and unaligned addresses change nothing
    test_id = 6;
    wr_ok(S8,  A_OUT, 32'h0000_0055, 4'hF);
    wr_ok(S8,  A_DIR, 32'h0000_000F, 4'hF);
    wr_ok(S32, A_OUT, 32'h0000_0055, 4'hF);
    wr_ok(S32, A_DIR, 32'h0000_000F, 4'hF);
    bad_addr(8'h24); bad_addr(8'h28); bad_addr(8'h3C); bad_addr(8'h40);
    bad_addr(8'h44); bad_addr(8'h4C); bad_addr(8'h60); bad_addr(8'h80);
    bad_addr(8'hFC); bad_addr(8'h01); bad_addr(8'h02); bad_addr(8'h03);
    bad_addr(8'h05); bad_addr(8'h21); bad_addr(8'h23);
    read_regs(S8,  32'h55, 32'h0F, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0);
    read_regs(S32, 32'h55, 32'h0F, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0);
    check32({24'h000000, gpio_out8}, 32'h0000_0055);
    check32({24'h000000, gpio_oe8},  32'h0000_000F);
    check32(gpio_out32, 32'h0000_0055);
    check32(gpio_oe32,  32'h0000_000F);

    // T7: rising edge on two pins, edge fires once, partial clear, mask
    test_id = 7;
    wr_ok(S8, A_RISE, 32'h0000_0003, 4'hF);
    gpio_in8[1:0] = 2'b11;
    tick(3);
    rd_ok(S8, A_STAT, 32'h0000_0003);
    check1(irq8, 1'b0);                     // masked condition still sets status
    wr_ok(S8, A_STAT, 32'h0000_0001, 4'hF); // clear one of two pending bits
    rd_ok(S8, A_STAT, 32'h0000_0002);
    tick(3);
    rd_ok(S8, A_STAT, 32'h0000_0002);       // held-high pin: edge does not fire again
    wr_ok(S8, A_EN, 32'h0000_0002, 4'hF);
    check1(irq8, 1'b1);                     // unmasking a pending bit raises irq
    wr_ok(S8, A_EN, 32'h0000_0001, 4'hF);
    check1(irq8, 1'b0);
    wr_ok(S8, A_EN, 32'h0000_0002, 4'hF);
    check1(irq8, 1'b1);
    wr_ok(S8, A_STAT, 32'h0000_0002, 4'hF);
    check1(irq8, 1'b0);
    rd_ok(S8, A_STAT, 32'h0000_0000);
    wr_ok(S8, A_EN,   32'h0000_0000, 4'hF);
    wr_ok(S8, A_RISE, 32'h0000_0000, 4'hF);

    // T8: falling edge
    test_id = 8;
    wr_ok(S8, A_FALL, 32'h0000_0004, 4'hF);
    gpio_in8[2] = 1'b1;
    tick(3);
    rd_ok(S8, A_STAT, 32'h0000_0000);
    gpio_in8[2] = 1'b0;
    tick(3);
    rd_ok(S8, A_STAT, 32'h0000_0004);
    tick(3);
    rd_ok(S8, A_STAT, 32'h0000_0004);
    wr_ok(S8, A_STAT, 32'h0000_0004, 4'hF);
    rd_ok(S8, A_STAT, 32'h0000_0000);
    tick(3);
    rd_ok(S8, A_STAT, 32'h0000_0000);
    wr_ok(S8, A_FALL, 32'h0000_0000, 4'hF);

    // T9: both edges on one pin
    test_id = 9;
    wr_ok(S8, A_RISE, 32'h0000_0008, 4'hF);
    wr_ok(S8, A_FALL, 32'h0000_0008, 4'hF);
    gpio_in8[3] = 1'b1;
    tick(3);
    rd_ok(S8, A_STAT, 32'h0000_0008);
    wr_ok(S8, A_STAT, 32'h0000_0008, 4'hF);
    rd_ok(S8, A_STAT, 32'h0000_0000);
    gpio_in8[3] = 1'b0;
    tick(3);
    rd_ok(S8, A_STAT, 32'h0000_0008);
    wr_ok(S8, A_STAT, 32'h0000_0008, 4'hF);
    rd_ok(S8, A_STAT, 32'h0000_0000);
    wr_ok(S8, A_RISE, 32'h0000_0000, 4'hF);
    wr_ok(S8, A_FALL, 32'h0000_0000, 4'hF);

    // T10: high level, exact timing, sets again after a clear
    test_id = 10;
    wr_ok(S8, A_HIGH, 32'h0000_0010, 4'hF);
    wr_ok(S8, A_EN,   32'h0000_0010, 4'hF);
    check1(irq8, 1'b0);
    rd_ok(S8, A_STAT, 32'h0000_0000);
    gpio_in8[4] = 1'b1;                     // driven before edge E
    tick(1);
    check1(irq8, 1'b0);                     // sampled on E, status not yet set
    tick(1);
    check1(irq8, 1'b1);                     // status set on E+1
    rd_ok(S8, A_STAT, 32'h0000_0010);
    wr_ok(S8, A_STAT, 32'h0000_0010, 4'hF);
    rd_ok(S8, A_STAT, 32'h0000_0010);       // level holds: clear does not stick
    check1(irq8, 1'b1);
    gpio_in8[4] = 1'b0;
    tick(3);
    rd_ok(S8, A_STAT, 32'h0000_0010);       // sticky
    wr_ok(S8, A_STAT, 32'h0000_0010, 4'hF);
    rd_ok(S8, A_STAT, 32'h0000_0000);
    check1(irq8, 1'b0);
    wr_ok(S8, A_HIGH, 32'h0000_0000, 4'hF);
    wr_ok(S8, A_EN,   32'h0000_0000, 4'hF);

    // T11: low level
    test_id = 11;
    wr_ok(S8, A_LOW, 32'h0000_0020, 4'hF);
    tick(3);
    rd_ok(S8, A_STAT, 32'h0000_0020);
    wr_ok(S8, A_STAT, 32'h0000_0020, 4'hF);
    rd_ok(S8, A_STAT, 32'h0000_0020);
    gpio_in8[5] = 1'b1;
    tick(3);
    wr_ok(S8, A_STAT, 32'h0000_0020, 4'hF);
    rd_ok(S8, A_STAT, 32'h0000_0000);
    wr_ok(S8, A_LOW, 32'h0000_0000, 4'hF);

    // T12: a detection beats a clear on the same edge
    test_id = 12;
    wr_ok(S8, A_RISE, 32'h0000_0040, 4'hF);
    gpio_in8[6] = 1'b1;
    tick(3);
    rd_ok(S8, A_STAT, 32'h0000_0040);
    gpio_in8[6] = 1'b0;
    tick(3);
    rd_ok(S8, A_STAT, 32'h0000_0040);
    gpio_in8[6] = 1'b1;                     // rise detected in the access cycle of the clear
    wr_ok(S8, A_STAT, 32'h0000_0040, 4'hF);
    rd_ok(S8, A_STAT, 32'h0000_0040);
    wr_ok(S8, A_STAT, 32'h0000_0040, 4'hF); // no new event: clear sticks
    rd_ok(S8, A_STAT, 32'h0000_0000);
    wr_ok(S8, A_RISE, 32'h0000_0000, 4'hF);

    // T13: N=32, strobed write-1-to-clear, bit 31, irq
    test_id = 13;
    wr_ok(S32, A_RISE, 32'h8000_0101, 4'hF);
    gpio_in32 = 32'h8000_0101;
    tick(3);
    rd_ok(S32, A_STAT, 32'h8000_0101);
    wr_ok(S32, A_STAT, 32'hFFFF_FFFF, 4'b0010);
    rd_ok(S32, A_STAT, 32'h8000_0001);
    wr_ok(S32, A_STAT, 32'h0000_0000, 4'hF);
    rd_ok(S32, A_STAT, 32'h8000_0001);
    wr_ok(S32, A_STAT, 32'h8000_0001, 4'b0111);
    rd_ok(S32, A_STAT, 32'h8000_0000);
    check1(irq32, 1'b0);
    wr_ok(S32, A_EN, 32'h8000_0000, 4'hF);
    check1(irq32, 1'b1);
    wr_ok(S32, A_STAT, 32'h8000_0000, 4'b1000);
    rd_ok(S32, A_STAT, 32'h0000_0000);
    check1(irq32, 1'b0);
    wr_ok(S32, A_HIGH, 32'h8000_0000, 4'hF);
    tick(3);
    rd_ok(S32, A_STAT, 32'h8000_0000);
    check1(irq32, 1'b1);
    wr_ok(S32, A_STAT, 32'h8000_0000, 4'hF);
    rd_ok(S32, A_STAT, 32'h8000_0000);
    wr_ok(S32, A_HIGH, 32'h0000_0000, 4'hF);
    wr_ok(S32, A_STAT, 32'h8000_0000, 4'hF);
    rd_ok(S32, A_STAT, 32'h0000_0000);
    check1(irq32, 1'b0);
    wr_ok(S32, A_EN,   32'h0000_0000, 4'hF);
    wr_ok(S32, A_RISE, 32'h0000_0000, 4'hF);
    rd_ok(S8, A_STAT, 32'h0000_0000);       // N=8 instance untouched

    // T14: reset again with state and a pending interrupt
    test_id = 14;
    wr_ok(S8,  A_OUT,  32'h0000_00A5, 4'hF);
    wr_ok(S8,  A_DIR,  32'h0000_00FF, 4'hF);
    wr_ok(S8,  A_HIGH, 32'h0000_0001, 4'hF);
    wr_ok(S8,  A_EN,   32'h0000_0001, 4'hF);
    wr_ok(S32, A_OUT,  32'hFFFF_FFFF, 4'hF);
    wr_ok(S32, A_DIR,  32'h8000_0001, 4'hF);
    tick(3);
    check1(irq8, 1'b1);
    check32({24'h000000, gpio_out8}, 32'h0000_00A5);
    check32({24'h000000, gpio_oe8},  32'h0000_00FF);
    check32(gpio_out32, 32'hFFFF_FFFF);
    check32(gpio_oe32,  32'h8000_0001);
    presetn = 1'b0;
    tick(1);
    chk_reset_outputs;
    tick(1);
    chk_reset_outputs;
    presetn = 1'b1;
    tick(1);
    read_regs(S8,  32'h0, 32'h0, {24'h000000, gpio_in8}, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0);
    read_regs(S32, 32'h0, 32'h0, gpio_in32,              32'h0, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0);
    check1(irq8, 1'b0);
    check1(irq32, 1'b0);

    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

  // Watchdog: a hung run fails with a verdict.
  initial begin
    #1000000;
    $error("TIMEOUT: testbench did not finish");
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + 1);
    $finish;
  end

endmodule
